#!/usr/bin/env bash

for _a in "$@"; do case "$_a" in --help|-h)
	printf 'usage: %s %s\n' "${0##*/}" ''
	printf '%s\n' 'Repo shell lint gate: shellcheck, bash syntax and the util smoke tests; takes no arguments.'
	exit 0;; esac; done
# >>> shguard modes=exec (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'tests/shell-gate.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  exec) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: exec; pipe callers set SHGUARD_MODE=pipe)\n' 'shell-gate.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
_bid="$(dirname "$(readlink -f "${BASH_SOURCE[0]}")")/../util/lib/build-id.sh"
# shellcheck source=util/lib/build-id.sh
[ -r "$_bid" ] && { . "$_bid"; build_flags "${BASH_SOURCE[0]}" "$@"; }
set -euo pipefail

repo_dir=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
cd "$repo_dir"

section() {
	printf '\n[%s]\n' "$1"
}

mapfile -d '' -t shell_files < <(git ls-files -z -- '*.sh')
if [[ ${#shell_files[@]} -eq 0 ]]; then
	printf 'No tracked shell files found.\n' >&2
	exit 1
fi

section 'ShellCheck'
# Warning level: info findings predate the disposition work (SC1091 not-following).
# sh-dialect files use `local`/`pipefail`, which dash supports; the disposition gate below lints them with -s dash.
shellcheck -S warning -e SC3040,SC3043 "${shell_files[@]}"

section 'Bash syntax'
for shell_file in "${shell_files[@]}"; do
	bash -n "$shell_file"
done

section 'Debian maintenance smoke'
bash util/tests/debian-maintenance.sh

section 'util router smoke'
bash util/tests/util-router.sh

section 'cache-prune smoke'
bash util/tests/cache-prune.sh

section 'battery smoke'
bash util/tests/battery.sh

section 'ip smoke'
bash util/tests/ip.sh

section 'push-all smoke'
bash util/tests/push-all.sh

section 'alias-chain smoke'
bash tests/aliases-smoke.sh

section 'root-utility smoke'
bash tests/root-utils-smoke.sh

section 'pkg-ioc smoke'
bash pkg-ioc/tests/smoke.sh

section 'build-system template compile'
(
	cd build_system
	./build.sh
)

section 'build-system smoke'
bash build_system/tests/smoke.sh

section 'shell disposition gate'
if command -v bun >/dev/null 2>&1 && [[ -f "$gate" ]]; then
	bun "$gate" .
else
	printf 'SKIPPED: bun or shell-disposition-gate.mjs not available\n'
fi

section 'public contract smoke'
bash tests/public-contract-smoke.sh

section 'blamecount smoke'
bash blamecount/tests/smoke.sh

printf '\nAll tracked shell gates passed.\n'
